def _surum_dosyasi_yolu():
    return os.path.join(PROJE_KOK_DIZINI, ".ar_studio_surum")


def eksik_modulleri_otomatik_olustur(zorla_yenile: bool = False):
    mevcut_surum = ""
    s_yol = _surum_dosyasi_yolu()
    if os.path.exists(s_yol):
        try:
            with open(s_yol, "r", encoding="utf-8") as sf:
                mevcut_surum = sf.read().strip()
        except Exception:
            pass
    guncelleme_gerekli = zorla_yenile or (mevcut_surum != AR_STUDIO_SURUM)
    for dosya_adi, b64_veri in _GOMULU_MODUL_ARSIVI.items():
        hedef_yol = os.path.join(PROJE_KOK_DIZINI, dosya_adi)
        if guncelleme_gerekli or (not os.path.exists(hedef_yol)) or os.path.getsize(hedef_yol) < 100:
            try:
                cozulen_kod = zlib.decompress(base64.b64decode(b64_veri)).decode("utf-8")
                with open(hedef_yol, "w", encoding="utf-8") as f_out:
                    f_out.write(cozulen_kod)
            except Exception:
                pass
    if guncelleme_gerekli:
        try:
            with open(s_yol, "w", encoding="utf-8") as sf:
                sf.write(AR_STUDIO_SURUM)
        except Exception:
            pass


eksik_modulleri_otomatik_olustur(zorla_yenile=False)


def modulu_bagla(modul_adi: str):
    importlib.invalidate_caches()
    if modul_adi in sys.modules:
        del sys.modules[modul_adi]
    if modul_adi in sys.modules and getattr(sys.modules[modul_adi], "__file__", None):
        return sys.modules[modul_adi]
    hedef_dosya = f"{modul_adi}.py"
    aday_yollar = [os.path.join(PROJE_KOK_DIZINI, hedef_dosya)]
    for yol in aday_yollar:
        if os.path.exists(yol) and os.path.getsize(yol) >= 100:
            try:
                spec = importlib.util.spec_from_file_location(modul_adi, yol)
                if spec and spec.loader:
                    mod = importlib.util.module_from_spec(spec)
                    sys.modules[modul_adi] = mod
                    spec.loader.exec_module(mod)
                    return mod
            except Exception:
                pass
    if hedef_dosya in _GOMULU_MODUL_ARSIVI:
        import types as _types
        cozulen_kod = zlib.decompress(base64.b64decode(_GOMULU_MODUL_ARSIVI[hedef_dosya])).decode("utf-8")
        mod = _types.ModuleType(modul_adi)
        mod.__file__ = os.path.join(PROJE_KOK_DIZINI, hedef_dosya)
        sys.modules[modul_adi] = mod
        exec(compile(cozulen_kod, mod.__file__, "exec"), mod.__dict__)
        return mod
    return __import__(modul_adi)


