def _sohbet_alani_goster(sohbet_dili: str, yukseklik: int = 440):
    q1, q2, q3, q4 = st.columns(4)
    hizli_girdi = None
    if q1.button("👤 Hakkımda", use_container_width=True, key="hz_hak"):
        hizli_girdi = "benim hakkımda ne biliyorsun"
    if q2.button("√ Köklü Sayı", use_container_width=True, key="hz_kok"):
        hizli_girdi = "kök 72"
    if q3.button("📊 Trigonometri", use_container_width=True, key="hz_trig"):
        hizli_girdi = "sin 30"
    if q4.button("📐 2. Der. Denklem", use_container_width=True, key="hz_denk"):
        hizli_girdi = "x^2 - 5x + 6 = 0"

    chat_penceresi = st.container(height=yukseklik)
    with chat_penceresi:
        for msg in st.session_state.messages:
            avatar = "👤" if msg["role"] == "user" else "⚡"
            with st.chat_message(msg["role"], avatar=avatar):
                st.markdown(msg["content"])
                saat_bilgi = msg.get("zaman", "")
                etiket_bilgi = msg.get("etiket", "")
                if saat_bilgi or etiket_bilgi:
                    st.caption(f"🕒 {saat_bilgi}  |  🏷️ {etiket_bilgi}")

    if st.session_state.get("son_ses_bayt"):
        try:
            st.audio(st.session_state.son_ses_bayt, format="audio/mp3", autoplay=True)
        except TypeError:
            st.audio(st.session_state.son_ses_bayt, format="audio/mp3")
        st.session_state.son_ses_bayt = None

    with st.expander("🎙️ Mikrofonla Sesli Soru Sor (Bas-Konuş)", expanded=False):
        if hasattr(st, "audio_input"):
            mikrofon_kaydi = st.audio_input("🎙️ Mikrofon simgesine dokunup sorunu söyle:")
            if mikrofon_kaydi is not None:
                ses_bayt_m = mikrofon_kaydi.getvalue()
                ses_hash = hash(ses_bayt_m)
                if ses_hash != st.session_state.get("son_mikrofon_hash"):
                    st.session_state["son_mikrofon_hash"] = ses_hash
                    cozulen_metin, hata_m = m5_dil.mikrofon_sesini_metne_cevir(ses_bayt_m, dil="tr-TR")
                    if cozulen_metin:
                        cevap_m, dil_m = mesaji_isle(cozulen_metin, sohbet_dili)
                        m5_dil.sesli_soyle(cevap_m, dil=dil_m, rerun_sonrasi=True)
                        st.rerun()
                    elif hata_m:
                        st.warning(hata_m)

    prompt = st.chat_input("Ar'a yaz... (İki cümle veya uzun soru sorabilirsin! Örn: 'Merhaba Ar nasılsın? Kök 128 kaçtır?')")
    aktif_girdi = hizli_girdi or prompt
    if aktif_girdi is not None and aktif_girdi.strip() != "":
        cevap, dil_kodu = mesaji_isle(aktif_girdi, sohbet_dili)
        m5_dil.sesli_soyle(cevap, dil=dil_kodu, rerun_sonrasi=True)
        st.rerun()

    bekleyen_soru = st.session_state.get("bekleyen_ogret_sorusu", "")
    with st.expander(
        f"🎓 Bana Öğretir misin? — {'Yeni Soru: ' + bekleyen_soru if bekleyen_soru else 'Kod Yazmadan Hızlı Soru-Cevap Öğret'}",
        expanded=bool(bekleyen_soru),
    ):
        with st.form("hizli_bana_ogret_formu", clear_on_submit=True):
            ogret_soru_input = st.text_input("Öğretilecek Soru veya Kelime:", value=bekleyen_soru)
            ogret_cevap_input = st.text_area("Ar'ın Vereceği Cevap:", height=85)
            if st.form_submit_button("💾 Öğret ve Hafızaya Kaydet (Kod Yazmadan)", use_container_width=True):
                if ogret_soru_input.strip() and ogret_cevap_input.strip():
                    kat_kodu = f"ogrenilen_{int(time.time())}"
                    m3_veri.json_komut_ekle(kat_kodu, ogret_soru_input.strip(), ogret_cevap_input.strip())
                    st.session_state["bekleyen_ogret_sorusu"] = ""
                    simdi_z = datetime.now()
                    st.session_state.messages.append({
                        "role": "assistant",
                        "content": f"✅ **Teşekkür ederim Ahmet, hemen öğrendim!** Artık **'{ogret_soru_input.strip()}'** dediğinde şu cevabı vereceğim:\n> {ogret_cevap_input.strip()}",
                        "zaman": simdi_z.strftime("%H:%M:%S"),
                        "tarih": simdi_z.strftime("%Y-%m-%d"),
                        "etiket": "Yeni Öğrenildi",
                    })
                    m3_veri.sohbet_gecmisi_kaydet(st.session_state.messages)
                    st.rerun()


def _json_studyo_goster():
    st.subheader("🧠 JSON Komut Stüdyosu")
    tab_ekle, tab_yonet = st.tabs(["➕ Yeni Cevap", "🗂️ JSON Yönetimi"])
    with tab_ekle:
        with st.form("yeni_komut_formu", clear_on_submit=True):
            kat_input = st.text_input("Kategori Adı:", placeholder="Örn: ozel_bilgiler")
            kelime_input = st.text_input("Anahtar Kelimeler (Virgülle):", placeholder="Örn: okulum, favori ders")
            yanit_input = st.text_area("Verilecek Cevap:", height=110)
            if st.form_submit_button("💾 JSON Dosyasına Kaydet", use_container_width=True):
                if kat_input and kelime_input and yanit_input:
                    m3_veri.json_komut_ekle(kat_input, kelime_input, yanit_input)
                    st.success(f"'{kat_input}' başarıyla kaydedildi!")
                    st.rerun()
    with tab_yonet:
        guncel_json = m3_veri.json_oku()
        if guncel_json:
            sil_secim = st.selectbox("Silinecek Kategori:", options=list(guncel_json.keys()))
            if st.button("🗑️ Seçili Kategoriyi Sil", use_container_width=True):
                m3_veri.json_kategori_sil(sil_secim)
                st.rerun()
        with st.expander("📄 Canlı komutlar.json İçeriği", expanded=True):
            st.json(guncel_json)


def sistemi_baslat():
    oturum_durumunu_hazirla()
    m1_arayuz.arayuz_stillerini_yukle(
        st.session_state.secili_tema,
        st.session_state.secili_arayuz_stili,
        st.session_state.cihaz_modu,
    )
    m3_veri.json_veritabani_hazirla()
    kalip_havuzu = m8_zeka.kalip_havuzu_olustur()

    STUDYO_LISTESI = [
        "💬 AI Chatbot & JSON Stüdyo",
        "🧮 Matematik & Fen Laboratuvarı",
        "📚 Ders & Notlar Merkezi",
        "📜 İslam Âlimleri Ansiklopedisi",
        "🌌 Görsel Bilim & Âlimler Atlası (102 Kişi)",
        "🌐 28 Dilli Çeviri & 100 Dil Kartı",
        "🚀 Ahmet Profil & İHA/Bebek Arabası Hesaplayıcı",
        "🇹🇷 TDK Türkçe & Cümle Stüdyosu",
        "📊 Sistem Dashboard & Tek Modül Kontrolü",
    ]

    with st.sidebar:
        st.markdown("## ⚡ Ar AI Kontrol Merkezi")
        st.caption(f"✅ **9 / 9 Modül Aktif ({AR_STUDIO_SURUM})**")

        # CİHAZ MODU SEÇİCİ (MASAÜSTÜ / MOBİL)
        st.markdown("### 🖥️ / 📱 Cihaz Modu")
        cm1, cm2 = st.columns(2)
        if cm1.button("🖥️ Masaüstü", key="sb_desk_btn", use_container_width=True):
            st.session_state.cihaz_modu = "Masaüstü"
            st.rerun()
        if cm2.button("📱 Mobil", key="sb_mob_btn", use_container_width=True):
            st.session_state.cihaz_modu = "Mobil"
            st.rerun()

        # API AÇ / KAPAT MODU
        st.markdown("### 🔌 API Kontrolü (Aç / Kapat)")
        ap1, ap2 = st.columns(2)
        if ap1.button("🟢 API Aç", key="sb_api_ac", use_container_width=True):
            st.session_state.api_aktif = True
            st.rerun()
        if ap2.button("🔴 API Kapat", key="sb_api_kapat", use_container_width=True):
            st.session_state.api_aktif = False
            st.rerun()

        if st.session_state.api_aktif:
            st.markdown('<span class="live-badge">🟢 API AÇIK (Canlı AI Bağlı)</span>', unsafe_allow_html=True)
        else:
            st.markdown('<span class="silent-badge">🔴 API KAPALI (Yerel Mod)</span>', unsafe_allow_html=True)

        bolum = st.radio("Çalışma Stüdyosu Seçin:", STUDYO_LISTESI, key="sb_bolum_secim")

        st.markdown("---")
        st.markdown("### 🎨 Tema & Arayüz Çeşitliliği")
        tema_listesi = list(m1_arayuz.TEMA_PALETLERI.keys())
        if st.session_state.secili_tema not in tema_listesi:
            st.session_state.secili_tema = tema_listesi[0]
        secilen_tema = st.selectbox(
            f"Renk Paleti ({len(tema_listesi)} Çeşit):",
            options=tema_listesi,
            index=tema_listesi.index(st.session_state.secili_tema),
        )
        if secilen_tema != st.session_state.secili_tema:
            st.session_state.secili_tema = secilen_tema
            st.rerun()

        stil_listesi = m1_arayuz.ARAYUZ_STILLERI
        secilen_stil = st.selectbox(
            f"Arayüz Stili ({len(stil_listesi)} Çeşit):",
            options=stil_listesi,
            index=stil_listesi.index(st.session_state.secili_arayuz_stili),
        )
        if secilen_stil != st.session_state.secili_arayuz_stili:
            st.session_state.secili_arayuz_stili = secilen_stil
            st.rerun()

        st.markdown("### 🎛️ Doğal Ses & Dil Ayarları")
        st.session_state.sessiz_mod = st.toggle("🤫 Sessiz Konuşma Modu", value=st.session_state.sessiz_mod)
        st.session_state.ses_aktif = st.toggle(
            "🔊 Doğal Ses Motoru (Neural + gTTS)",
            value=st.session_state.ses_aktif,
            disabled=st.session_state.sessiz_mod,
        )
        st.session_state.ses_cinsiyet = st.selectbox(
            "🎙️ Ses Karakteri:",
            options=["Erkek", "Kadın"],
            format_func=lambda x: "👨 Ahmet Neural (Erkek)" if x == "Erkek" else "👩 Emel Neural (Kadın)",
            disabled=st.session_state.sessiz_mod or not st.session_state.ses_aktif,
        )
        sohbet_dili = st.selectbox(
            f"Yanıt Dili ({len(m5_dil.DESTEKLENEN_DILLER)} Dil):",
            options=list(m5_dil.DESTEKLENEN_DILLER.keys()),
            format_func=lambda x: m5_dil.DESTEKLENEN_DILLER[x],
        )

        st.markdown("---")
        st.markdown("### 🔑 Gemini & Grok/Groq API")
        st.session_state.hibrit_ai_aktif = st.toggle("🧠 Hibrit AI Aktif", value=st.session_state.hibrit_ai_aktif)
        sb_key = st.text_input(
            "Aktif API Anahtarı (Gemini / Grok / Groq):",
            value=st.session_state.aktif_api_key,
            type="password",
        )
        if sb_key.strip() != st.session_state.aktif_api_key:
            st.session_state.aktif_api_key = sb_key.strip()
        st.session_state.grok_api_key = st.text_input(
            "⚡ Ek Grok / Groq Anahtarı (İsteğe Bağlı):",
            value=st.session_state.grok_api_key,
            placeholder="gsk_... veya xai-...",
            type="password",
        )
        if st.session_state.grok_api_key.strip() and st.session_state.aktif_api_key == VARSAYILAN_API_KEY:
            st.session_state.aktif_api_key = st.session_state.grok_api_key.strip()
        if st.button("🔌 API Bağlantısını Test Et", use_container_width=True, key="btn_api_test"):
            with st.spinner("API bağlantısı test ediliyor..."):
                _test_fn = getattr(m8_zeka, "api_baglanti_testi", None)
                if _test_fn is not None:
                    ok_api, msg_api = _test_fn(st.session_state.aktif_api_key, st.session_state.api_saglayici_secimi)
                else:
                    eksik_modulleri_otomatik_olustur(zorla_yenile=True)
                    ok_api, msg_api = False, "Modül 8 yeni sürüme güncellendi; lütfen sayfayı yenileyip (F5) tekrar deneyin."
            if ok_api:
                st.success(msg_api)
            else:
                st.error(f"Bağlantı Hatası: {msg_api}")
        if st.session_state.get("son_api_hatasi"):
            st.caption(f"⚠️ Son API uyarısı: {st.session_state['son_api_hatasi'][:180]}")

        st.markdown("---")
        st.session_state.masaustu_gecmis_acik = st.toggle("💬 Geçmiş Baloncukları Göster", value=st.session_state.masaustu_gecmis_acik)
        if st.session_state.masaustu_gecmis_acik:
            kullanici_sorulari = [m for m in st.session_state.messages if m["role"] == "user"]
            bugun_tarih = datetime.now().strftime("%Y-%m-%d")
            dun_tarih = (datetime.now() - timedelta(days=1)).strftime("%Y-%m-%d")
            gruplar = {"Bugün": [], "Dün": [], "Önceki": []}
            for m in reversed(kullanici_sorulari):
                t = m.get("tarih", bugun_tarih)
                if t == bugun_tarih:
                    gruplar["Bugün"].append(m)
                elif t == dun_tarih:
                    gruplar["Dün"].append(m)
                else:
                    gruplar["Önceki"].append(m)

            with st.container(height=190):
                for grup_adi, liste in gruplar.items():
                    if liste:
                        st.markdown(f'<div class="bubble-group-header">📅 {grup_adi} ({len(liste)})</div>', unsafe_allow_html=True)
                        for m in liste:
                            saat = m.get("zaman", "--:--")
                            etiket = m.get("etiket", "Sohbet")
                            kisa = m["content"][:32] + "..." if len(m["content"]) > 32 else m["content"]
                            st.markdown(m1_arayuz.sohbet_baloncuk_karti_olustur(etiket, saat, kisa), unsafe_allow_html=True)

        col_sb1, col_sb2 = st.columns(2)
        with col_sb1:
            st.download_button(
                label="📥 Yedekle",
                data=json.dumps(st.session_state.messages, ensure_ascii=False, indent=2),
                file_name=f"ar_gecmis_{datetime.now().strftime('%Y%m%d_%H%M')}.json",
                mime="application/json",
                use_container_width=True,
            )
        with col_sb2:
            if st.button("🗑️ Temizle", use_container_width=True):
                st.session_state.messages = [
                    {
                        "role": "assistant",
                        "content": "Sohbet geçmişi sıfırlandı Ahmet! Yeni konuşmaya hazırız. ⚡",
                        "zaman": datetime.now().strftime("%H:%M:%S"),
                        "tarih": datetime.now().strftime("%Y-%m-%d"),
                        "etiket": "Sıfırlandı",
                    }
                ]
                m3_veri.sohbet_gecmisi_kaydet(st.session_state.messages)
                st.rerun()

    # ÜST HERO BANNER
    m1_arayuz.hero_banner_goster(
        len(kalip_havuzu),
        st.session_state.secili_tema,
        st.session_state.cihaz_modu,
        st.session_state.api_aktif,
    )

    # MASAÜSTÜ VE MOBİL KONTROL ÇUBUĞU
    if st.session_state.cihaz_modu == "Masaüstü":
        masaustu_kontrol_cubugu_goster()
    else:
        mobil_kontrol_cubugu_goster()
        bolum = st.selectbox("📱 Stüdyo Seç:", STUDYO_LISTESI, index=STUDYO_LISTESI.index(bolum), key="mob_bolum_secim")

    api_baglanti_kutusu_goster()

    # STÜDYO YÖNLENDİRMELERİ
    if bolum == "💬 AI Chatbot & JSON Stüdyo":
        if st.session_state.cihaz_modu == "Masaüstü":
            if st.session_state.masaustu_json_panel_acik:
                col_chat, col_studio = st.columns([2.15, 1.15], gap="large")
                with col_chat:
                    st.subheader("💬 Canlı Asistan Sohbeti (Masaüstü Modu)")
                    _sohbet_alani_goster(sohbet_dili, yukseklik=450)
                with col_studio:
                    _json_studyo_goster()
            else:
                st.subheader("💬 Canlı Asistan Sohbeti (Geniş Masaüstü Odak Modu)")
                _sohbet_alani_goster(sohbet_dili, yukseklik=500)
        else:
            st.subheader("💬 Canlı Sohbet (Mobil Modu)")
            _sohbet_alani_goster(sohbet_dili, yukseklik=380)
            with st.expander("🧠 JSON Komut Stüdyosu (Aç / Kapat)", expanded=False):
                _json_studyo_goster()

    elif bolum == "🧮 Matematik & Fen Laboratuvarı":
        m4_matematik.matematik_studyosu_goster(m5_dil.sesli_soyle)

    elif bolum == "📚 Ders & Notlar Merkezi":
        m7_ders.ders_ve_notlar_studyosu_goster(m5_dil.sesli_soyle)

    elif bolum == "📜 İslam Âlimleri Ansiklopedisi":
        m2_alimler.islam_alimleri_studyosu_goster(m5_dil.sesli_soyle)

    elif bolum == "🌌 Görsel Bilim & Âlimler Atlası (102 Kişi)":
        m9_atlas.gorsel_bilim_atlasi_studyosu_goster(m5_dil.sesli_soyle)

    elif bolum == "🌐 28 Dilli Çeviri & 100 Dil Kartı":
        m5_dil.dil_ve_cevirmeli_kart_studyosu_goster()

    elif bolum == "🚀 Ahmet Profil & İHA/Bebek Arabası Hesaplayıcı":
        m6_muhendislik.iha_ve_bebek_arabasi_studyosu_goster()

    elif bolum == "🇹🇷 TDK Türkçe & Cümle Stüdyosu":
        st.subheader("🇹🇷 TDK Türkçe Dilbilgisi, Sözlük & Bağlamsal Cümle Kurma Stüdyosu")
        t_tab1, t_tab2, t_tab3, t_tab4 = st.tabs([
            "📖 TDK Sözlük İndir & Ara",
            "📜 Deyim & Atasözü Sözlüğü",
            "✍️ Bağlamsal Cümle Kurma Motoru",
            "🔍 TDK Yazım & Ses Uyumu Denetleyici",
        ])

        with t_tab1:
            st.markdown("Python üzerinden resmi **TDK Güncel Türkçe Sözlük** (`sozluk.gov.tr/autocomplete.json`) kelime listesini indirip yerel önbelleğe alabilir ve canlı anlam sorgulayabilirsin.")
            indirilen = m8_zeka.tdk_yerel_sozluk_yukle()
            c_tdk1, c_tdk2 = st.columns([1.4, 1.6])
            with c_tdk1:
                if st.button("📥 TDK Resmi Sözlüğü İndir (Python)", use_container_width=True, key="btn_tdk_indir"):
                    with st.spinner("TDK sözlüğü sozluk.gov.tr üzerinden indiriliyor..."):
                        ok_t, sayi_t, msg_t = m8_zeka.tdk_sozluk_indir()
                    if ok_t:
                        st.success(msg_t)
                    else:
                        st.warning(msg_t)
            with c_tdk2:
                st.info(f"📚 Yerel TDK Önbelleği: **{len(indirilen):,}** sözcük | Çekirdek Sözlük: **{len(m8_zeka.TDK_CEKIRDEK_SOZLUK)}** sözcük".replace(",", "."))
                _kurulu_nlp = m8_zeka.kurulu_turkce_kutuphaneleri_algila()
                _ogrenilen_sayi = len(m8_zeka._tdk_anlam_onbellek_oku())
                st.caption(f"🔌 Kurulu Türkçe Kütüphaneler: {', '.join(_kurulu_nlp) if _kurulu_nlp else 'Yerleşik Morfoloji Motoru'} | 🧠 Öğrenilen TDK Kavramı: **{_ogrenilen_sayi}**")

            aranan_kelime = st.text_input("🔎 TDK Sözlükte Kelime Ara:", placeholder="Örn: algoritma, bilim, geliştirme, otonom...")
            if st.button("📖 Anlamını Getir", key="btn_tdk_ara") and aranan_kelime.strip():
                sonuc_t = m8_zeka.tdk_kelime_ara(aranan_kelime)
                if sonuc_t:
                    st.success(f"**{sonuc_t['madde']}** — *{sonuc_t['kaynak']}*")
                    for idx, anl in enumerate(sonuc_t["anlamlar"], 1):
                        st.markdown(f"**{idx}.** {anl}")
                    if sonuc_t.get("ornekler"):
                        st.caption(f"💬 Örnek: *{sonuc_t['ornekler'][0]}*")
                else:
                    st.warning("Kelime bulunamadı; internet bağlantısını veya kelime yazımını kontrol et.")

        with t_tab2:
            st.markdown("TDK **Özne + Zaman/Yer + Nesne (Hal Eki) + Yüklem (Kip/Kişi)** kurallarına göre bağlamsal Türkçe cümle üret.")
            b1, b2, b3 = st.columns(3)
            with b1:
                sec_baglam = st.selectbox("🎯 Bağlam / Konu:", ["Teknoloji & Yapay Zeka", "Eğitim & Bilim", "İHA & Mühendislik", "Doğa & Çevre", "Tarih & Kültür", "Günlük Yaşam"])
            with b2:
                sec_ozne = st.selectbox("👤 Özne / Kişi:", ["ben", "sen", "o", "biz", "siz", "onlar"])
            with b3:
                sec_zaman = st.selectbox("⏱️ Zaman / Kip:", ["şimdiki", "geçmiş_görülen", "geçmiş_öğrenilen", "gelecek", "geniş", "gereklilik"])

            o1, o2, o3, o4 = st.columns([1.4, 1.4, 0.8, 0.8])
            with o1:
                ozel_nesne = st.text_input("Özel Nesne (isteğe bağlı):", placeholder="Örn: kitap, yazılım, algoritma")
            with o2:
                ozel_fiil = st.text_input("Özel Fiil Mastarı (isteğe bağlı):", placeholder="Örn: yazmak, okumak, tasarlamak")
            with o3:
                olumsuz_mu = st.checkbox("Olumsuz", value=False)
            with o4:
                soru_mu = st.checkbox("Soru", value=False)

            if st.button("✨ TDK Kurallarıyla Cümle Kur", use_container_width=True, key="btn_tdk_cumle"):
                cumle_out, cozum_out = m8_zeka.tdk_baglamsal_cumle_kur(
                    baglam=sec_baglam,
                    ozne_kisi=sec_ozne,
                    zaman=sec_zaman,
                    ozel_nesne=ozel_nesne,
                    ozel_fiil=ozel_fiil,
                    olumsuz=olumsuz_mu,
                    soru=soru_mu,
                )
                st.success(f"### 🗣️ {cumle_out}")
                st.markdown(cozum_out)

        with t_tab3:
            kontrol_metin = st.text_area("✍️ Denetlenecek Türkçe Metni Gir:", placeholder="Örn: Herkez yalnış birşeyler söylüyor, yarın geliyormusun?")
            if st.button("🔍 TDK Yazım & Ses Uyumu Denetle", use_container_width=True, key="btn_tdk_yazim") and kontrol_metin.strip():
                bulgular, duzeltilmis, uyum_list = m8_zeka.tdk_yazim_denetle(kontrol_metin)
                if bulgular:
                    for b in bulgular:
                        st.warning(b)
                    st.success(f"✅ **Düzeltilmiş Öneri:** {duzeltilmis}")
                else:
                    st.success("✅ Metinde yaygın TDK yazım hatası tespit edilmedi.")
                if uyum_list:
                    st.markdown("**🔤 Ünlü Uyumu Analizi:** " + " · ".join(uyum_list))


        with t_tab4:
            st.markdown("TDK **Atasözleri ve Deyimler Sözlüğü** içinden arama yapabilir veya rastgele deyim/atasözü inceleyebilirsin.")
            ad_ara = st.text_input("🔎 Deyim veya Atasözü Ara:", placeholder="Örn: gözden düşmek, damlaya damlaya göl olur...", key="tdk_ad_ara")
            ad_tur = st.radio("Tür Filtresi:", ["Tümü", "Deyim", "Atasözü"], horizontal=True, key="tdk_ad_tur")
            if st.button("📜 Deyim / Atasözü Anlamını Getir", key="btn_tdk_ad") and ad_ara.strip():
                filtre = "" if ad_tur == "Tümü" else ad_tur
                ad_sonuc = m8_zeka.tdk_atasozu_deyim_ara(ad_ara, tur_filtre=filtre)
                if ad_sonuc:
                    st.success(f"**{ad_sonuc['madde']}** *({ad_sonuc['tur']} — {ad_sonuc['kaynak']})*")
                    st.markdown(f"**Anlamı:** {ad_sonuc['anlam']}")
                    if ad_sonuc.get("ornek"):
                        st.info(f"💬 **Örnek:** {ad_sonuc['ornek']}")
                else:
                    st.warning("Bu ifade için sonuç bulunamadı.")
            with st.expander(f"📚 Yerleşik TDK Deyim & Atasözü Arşivi ({len(m8_zeka.TDK_ATASOZU_VE_DEYIMLER_SOZLUGU)} Kayıt)", expanded=False):
                for _bas, _ver in list(m8_zeka.TDK_ATASOZU_VE_DEYIMLER_SOZLUGU.items())[:25]:
                    st.markdown(f"• **`{_bas}`** *({_ver['tur']})*: {_ver['anlam']}")

    elif bolum == "📊 Sistem Dashboard & Tek Modül Kontrolü":
        st.subheader("📊 Tekte Çalışan 8 Modüllü Kurumsal Mimari Analitiği")
        m1, m2, m3, m4 = st.columns(4)
        m1.metric("Hazır AI Kalıbı", f"{len(kalip_havuzu):,}".replace(",", "."), "O(1) İndeks")
        m2.metric("Bağlı Modül Sayısı", "9 / 9 Modül", AR_STUDIO_SURUM)
        m3.metric("Tema & Stil", f"{len(m1_arayuz.TEMA_PALETLERI)} Tema", f"{len(m1_arayuz.ARAYUZ_STILLERI)} Stil")
        m4.metric("3D Çevirmeli Kart", f"{len(m5_dil.A1_A2_DIL_PRATIK_KARTLARI)} Kart", "EN / AR / BN")

        st.markdown("---")
        c1, c2 = st.columns(2, gap="large")
        with c1:
            st.markdown("### 🔗 Tekte Kurulan ve Yönetilen 8 Modül")
            if st.button("🔄 8 Modül Dosyasını Proje Klasöründe Yeniden Oluştur / Güncelle", use_container_width=True):
                eksik_modulleri_otomatik_olustur(zorla_yenile=True)
                st.success("8 modül dosyası proje klasörüne v5.0 olarak yazıldı ve güncellendi!")
                st.rerun()
            for m_no, m_dosya, m_aciklama, m_aktif in MODUL_DURUM_LISTESI:
                durum = "✅ AKTİF VE BAĞLI" if m_aktif else "❌ BULUNAMADI"
                st.markdown(m1_arayuz.bilgi_karti_olustur(f"📦 {m_no}: {m_dosya}", durum, m_aciklama), unsafe_allow_html=True)
        with c2:
            st.markdown("### ⌨️ PyCharm & Masaüstü Hızlı Kısayol Rehberi")
            for k_item in m1_arayuz.SISTEM_KISAYOL_REHBERI:
                st.markdown(m1_arayuz.bilgi_karti_olustur(f"⌨️ {k_item['tus']}", k_item["platform"], k_item["aciklama"]), unsafe_allow_html=True)


if __name__ == "__main__":
    sistemi_baslat()